'use strict';

/**
 * drift-comparator.js — csd-s6: type-specific structural drift comparison
 * between an as-designed diagram (csd-s3/csd-s4, emitted as a CANVAS-JSON
 * marker embedded in `design.md`/an epic artefact) and an as-built diagram
 * (csd-s5, generated by static parsing of real repo files), producing an
 * explicit MATCHED/DIVERGED signal per diagram type — the epic's primary
 * benefit mechanism (benefit-metric.md P1: Time-to-drift-determination; P3:
 * Diverged-flag true-positive rate; M1: Drift caught before it became a
 * problem).
 *
 * Per this story's DoR Coding Agent Instructions, drift rules are
 * type-specific, not one generic rule:
 *   - Data Model: any table/column/relationship add-remove-rename, AND a
 *     specific non-optimal-design flag (ADR-026: reuse an existing
 *     entity/primitive when its shape already covers a new concept, rather
 *     than introducing a new one) when a new table's column shape
 *     substantially duplicates an existing as-designed entity.
 *   - Program Design: call-stack/file-tree structural changes only — the
 *     mermaid `flowchart` representation this compares never captures
 *     internal variable names, so a pure local rename can never appear as a
 *     node/edge difference; this is what makes the AC2 negative case
 *     (renamed local variable does not flag) true by construction, not by a
 *     special-cased exclusion rule.
 *   - System Architecture: new/removed service-to-service calls (edges)
 *     only — node-only additions are out of this rule's scope per AC3.
 *
 * This module never re-generates a diagram and never re-prompts an agent —
 * it operates purely on two already-produced diagram representations
 * (mermaid source strings, or the parsed structures csd-s5's modules already
 * produce), so the comparison itself is inherently fast (no model latency
 * reintroduced into this step — NFR: performance).
 *
 * Column-type-token comparison is deliberately NOT part of the Data Model
 * drift rule: this repo's own migration-schema-parser.js `mapType()` (as-built
 * side) and skills/design/SKILL.md's own worked examples (as-designed side)
 * do not use the same type-token vocabulary for the same SQL type today (e.g.
 * a `TEXT` column renders as `string` via mapType() but as `text` in the
 * documented as-designed convention) — a pre-existing inconsistency from
 * csd-s4/csd-s5, flagged in this story's PR description rather than silently
 * worked around. AC1 itself only requires flagging on add/remove/rename of
 * tables/columns/relationships, not on type-token wording, so keying column
 * identity on name alone (not type) is both correct per the AC and unaffected
 * by that inconsistency.
 */

// Injectable audit logger (NFR — drift check results are logged: matched or
// diverged, per diagram type, per feature — this is the evidence P3 and M1
// measurement depends on). Defaults to a no-op so importing this module
// never has a side effect on its own, mirroring
// src/modules/migration-schema-parser.js's own setLogger() convention.
let _logger = {
  info: function() {},
  warn: function() {}
};
function setLogger(logger) {
  _logger = logger;
}
function _logEvent(eventName, data) {
  try {
    _logger.info(eventName, data);
  } catch (e) {
    // Logging must never break drift comparison.
  }
}

// ---------------------------------------------------------------------------
// Parsing — Data Model (mermaid erDiagram)
// ---------------------------------------------------------------------------

const ENTITY_OPEN_RE = /^([A-Za-z_][A-Za-z0-9_]*)\s*\{$/;
const COLUMN_LINE_RE = /^(\S+)\s+([A-Za-z_][A-Za-z0-9_]*)(?:\s+(PK|FK))?\s*$/;
const RELATIONSHIP_RE = /^([A-Za-z_][A-Za-z0-9_]*)\s*([|o}{.\-]+)\s*([A-Za-z_][A-Za-z0-9_]*)\s*:\s*"([^"]*)"\s*$/;

/**
 * Parse a mermaid `erDiagram` string into `{tables: [{name, columns, foreignKeys}]}`
 * — the SAME shape src/modules/migration-schema-parser.js produces from real
 * migration files, so both sides of the comparison are directly comparable
 * regardless of which side (as-designed vs as-built) they came from.
 * Whitespace/indentation-agnostic (mermaid syntax itself does not require
 * specific indentation, and this repo's own worked examples use different
 * indentation conventions in different places).
 * @param {string} mermaidSrc
 * @returns {{tables: Array<{name:string, columns:Array, foreignKeys:Array}>}}
 */
function parseErDiagramMermaid(mermaidSrc) {
  const lines = String(mermaidSrc || '')
    .split('\n')
    .map(function(l) { return l.trim(); })
    .filter(function(l) { return l.length > 0 && l !== 'erDiagram'; });

  const tables = [];
  const relationshipLines = [];
  let current = null;

  lines.forEach(function(line) {
    if (current) {
      if (line === '}') {
        tables.push(current);
        current = null;
        return;
      }
      const colMatch = COLUMN_LINE_RE.exec(line);
      if (colMatch) {
        current.columns.push({
          name: colMatch[2],
          rawType: colMatch[1],
          isPrimaryKey: colMatch[3] === 'PK',
          isForeignKey: colMatch[3] === 'FK'
        });
      }
      return;
    }

    const openMatch = ENTITY_OPEN_RE.exec(line);
    if (openMatch) {
      current = { name: openMatch[1], columns: [], foreignKeys: [] };
      return;
    }

    const relMatch = RELATIONSHIP_RE.exec(line);
    if (relMatch) {
      relationshipLines.push({ left: relMatch[1], right: relMatch[3], label: relMatch[4] });
    }
  });

  // Relationship lines follow migration-schema-parser.generateErDiagram()'s
  // own convention: `<refTable> <cardinality> <table> : "<fkColumn>"` — the
  // right-hand table holds the foreign key named by the relationship label.
  relationshipLines.forEach(function(rel) {
    const rightTable = tables.find(function(t) { return t.name.toLowerCase() === rel.right.toLowerCase(); });
    if (rightTable) {
      rightTable.foreignKeys.push({ column: rel.label, refTable: rel.left });
    }
  });

  return { tables: tables };
}

// ---------------------------------------------------------------------------
// Parsing — Program Design / System Architecture (mermaid flowchart)
// ---------------------------------------------------------------------------

const NODE_DECL_RE = /^([A-Za-z0-9_]+)\s*(?:\[\(([^)]*)\)\]|\[([^\]]*)\])\s*$/;
const EDGE_RE = /^([A-Za-z0-9_]+)\s*-->\s*([A-Za-z0-9_]+)\s*$/;

/**
 * Parse a mermaid `flowchart` string into `{nodes, edges}`, where edges carry
 * both the raw mermaid node id AND the node's label (the file path / service
 * name) — comparisons key on LABEL, not id, because the as-designed and
 * as-built sides use different id conventions for the same real file/service
 * (csd-s5's call-graph-extractor.js sanitises the full path into the id,
 * while skills/design/SKILL.md's worked examples use short semantic ids like
 * `ROUTE`/`ADAPTER` — only the bracketed label text is the real, comparable
 * identity on both sides).
 * @param {string} mermaidSrc
 * @returns {{nodes: Array<{id:string,label:string}>, edges: Array<{from:string,to:string,fromLabel:string,toLabel:string}>}}
 */
function parseFlowchartMermaid(mermaidSrc) {
  const lines = String(mermaidSrc || '')
    .split('\n')
    .map(function(l) { return l.trim(); })
    .filter(Boolean);

  const idToLabel = {};
  const edgeIdPairs = [];

  lines.forEach(function(line) {
    if (/^flowchart\b/i.test(line)) return;

    const nodeMatch = NODE_DECL_RE.exec(line);
    if (nodeMatch) {
      const id = nodeMatch[1];
      let label = nodeMatch[2] !== undefined ? nodeMatch[2] : nodeMatch[3];
      label = String(label || '').replace(/^"|"$/g, '');
      idToLabel[id] = label;
      return;
    }

    const edgeMatch = EDGE_RE.exec(line);
    if (edgeMatch) {
      edgeIdPairs.push({ from: edgeMatch[1], to: edgeMatch[2] });
    }
  });

  function labelOf(id) { return idToLabel[id] !== undefined ? idToLabel[id] : id; }

  const nodes = Object.keys(idToLabel).map(function(id) { return { id: id, label: idToLabel[id] }; });
  const edges = edgeIdPairs.map(function(e) {
    return { from: e.from, to: e.to, fromLabel: labelOf(e.from), toLabel: labelOf(e.to) };
  });

  return { nodes: nodes, edges: edges };
}

// ---------------------------------------------------------------------------
// Signal shape
// ---------------------------------------------------------------------------

/**
 * Build the explicit MATCHED/DIVERGED signal (AC4 — never silence; AC5 —
 * every diverged signal names the specific difference).
 * @param {string[]} differences
 * @returns {{status:string, label:string, differences:string[]}}
 */
function _buildSignal(differences) {
  const diverged = differences.length > 0;
  return {
    status: diverged ? 'DIVERGED' : 'MATCHED',
    label: diverged ? 'Diverged' : 'Matches',
    differences: differences
  };
}

function _asTableSchema(input) {
  if (typeof input === 'string') return parseErDiagramMermaid(input);
  return input && input.tables ? input : { tables: [] };
}

function _asFlowchart(input) {
  if (typeof input === 'string') return parseFlowchartMermaid(input);
  return input && (input.nodes || input.edges) ? input : { nodes: [], edges: [] };
}

// ---------------------------------------------------------------------------
// Data Model drift rule (AC1)
// ---------------------------------------------------------------------------

// ADR-026 duplicate-entity heuristic threshold — a new table whose column
// name set overlaps an existing as-designed entity's column set at or above
// this Jaccard-similarity ratio is flagged as a likely non-optimal-design
// duplicate rather than a plain "table added" note.
const DUPLICATE_SIMILARITY_THRESHOLD = 0.5;

function _tableMapByLowerName(tables) {
  const map = {};
  (tables || []).forEach(function(t) { map[t.name.toLowerCase()] = t; });
  return map;
}

function _columnNames(table) {
  return (table.columns || []).map(function(c) { return c.name; });
}

function _jaccard(aArr, bArr) {
  const a = new Set(aArr);
  const b = new Set(bArr);
  if (a.size === 0 && b.size === 0) return 0;
  let intersection = 0;
  a.forEach(function(x) { if (b.has(x)) intersection++; });
  const union = new Set(aArr.concat(bArr)).size;
  return union === 0 ? 0 : intersection / union;
}

/**
 * Compare an as-designed Data Model diagram against an as-built one (AC1).
 * Accepts either a mermaid `erDiagram` source string or an already-parsed
 * `{tables:[...]}` object (e.g. directly from
 * migration-schema-parser.generateAsBuiltDataModelDiagram()'s `.schema`) on
 * either side.
 * @param {string|object} asDesignedInput
 * @param {string|object} asBuiltInput
 * @returns {{status:string, label:string, differences:string[]}}
 */
function compareDataModel(asDesignedInput, asBuiltInput) {
  const asDesigned = _asTableSchema(asDesignedInput);
  const asBuilt = _asTableSchema(asBuiltInput);

  const designedMap = _tableMapByLowerName(asDesigned.tables);
  const builtMap = _tableMapByLowerName(asBuilt.tables);

  const differences = [];

  // Tables added in as-built, not present in as-designed.
  Object.keys(builtMap).forEach(function(lowerName) {
    if (designedMap[lowerName]) return;
    const newTable = builtMap[lowerName];
    const newCols = _columnNames(newTable);

    // ADR-026: does an EXISTING as-designed entity's column shape already
    // substantially cover this concept?
    let bestMatch = null;
    let bestScore = 0;
    Object.keys(designedMap).forEach(function(existingLowerName) {
      const existingTable = designedMap[existingLowerName];
      const score = _jaccard(newCols, _columnNames(existingTable));
      if (score > bestScore) { bestScore = score; bestMatch = existingTable; }
    });

    if (bestMatch && bestScore >= DUPLICATE_SIMILARITY_THRESHOLD) {
      differences.push(
        'New table `' + newTable.name + '` added, but its columns (' + newCols.join(', ') +
        ') substantially duplicate existing entity `' + bestMatch.name + '` (' +
        _columnNames(bestMatch).join(', ') + ') — per ADR-026 (reuse an existing entity/primitive ' +
        'when its shape already covers a new concept), consider reusing or extending `' + bestMatch.name +
        '` instead of introducing a new entity.'
      );
    } else {
      differences.push('New table `' + newTable.name + '` added, no matching entity in the as-designed diagram.');
    }
  });

  // Tables present in as-designed but missing from as-built.
  Object.keys(designedMap).forEach(function(lowerName) {
    if (builtMap[lowerName]) return;
    differences.push('Table `' + designedMap[lowerName].name + '` is present in the as-designed diagram but missing from the as-built schema.');
  });

  // Column-level diffs on tables present on both sides.
  Object.keys(designedMap).forEach(function(lowerName) {
    const builtTable = builtMap[lowerName];
    if (!builtTable) return; // already reported above as removed
    const designedTable = designedMap[lowerName];
    const designedCols = _columnNames(designedTable);
    const builtCols = _columnNames(builtTable);

    builtCols.forEach(function(c) {
      if (designedCols.indexOf(c) === -1) {
        differences.push('Column `' + c + '` on table `' + designedTable.name + '` was added in as-built, not present in the as-designed diagram.');
      }
    });
    designedCols.forEach(function(c) {
      if (builtCols.indexOf(c) === -1) {
        differences.push('Column `' + c + '` on table `' + designedTable.name + '` is present in the as-designed diagram but missing from the as-built schema.');
      }
    });
  });

  return _buildSignal(differences);
}

// ---------------------------------------------------------------------------
// Program Design / System Architecture drift rules (AC2, AC3)
// ---------------------------------------------------------------------------

function _edgeKey(fromLabel, toLabel) { return fromLabel + ' --> ' + toLabel; }

function _diffNodesAndEdges(asDesigned, asBuilt, options) {
  options = options || {};
  const includeNodes = options.includeNodes !== false;

  const designedNodeLabels = {};
  (asDesigned.nodes || []).forEach(function(n) { designedNodeLabels[n.label] = true; });
  const builtNodeLabels = {};
  (asBuilt.nodes || []).forEach(function(n) { builtNodeLabels[n.label] = true; });

  const designedEdgeMap = {};
  (asDesigned.edges || []).forEach(function(e) { designedEdgeMap[_edgeKey(e.fromLabel, e.toLabel)] = e; });
  const builtEdgeMap = {};
  (asBuilt.edges || []).forEach(function(e) { builtEdgeMap[_edgeKey(e.fromLabel, e.toLabel)] = e; });

  const differences = [];

  if (includeNodes) {
    Object.keys(builtNodeLabels).forEach(function(label) {
      if (!designedNodeLabels[label]) {
        differences.push('New file/module `' + label + '` present in the as-built structure, not in the as-designed diagram.');
      }
    });
    Object.keys(designedNodeLabels).forEach(function(label) {
      if (!builtNodeLabels[label]) {
        differences.push('File/module `' + label + '` present in the as-designed diagram is missing from the as-built structure.');
      }
    });
  }

  Object.keys(builtEdgeMap).forEach(function(key) {
    if (!designedEdgeMap[key]) {
      const e = builtEdgeMap[key];
      differences.push('New call from `' + e.fromLabel + '` to `' + e.toLabel + '` present in the as-built structure, not in the as-designed diagram.');
    }
  });
  Object.keys(designedEdgeMap).forEach(function(key) {
    if (!builtEdgeMap[key]) {
      const e = designedEdgeMap[key];
      differences.push('Call from `' + e.fromLabel + '` to `' + e.toLabel + '` present in the as-designed diagram is missing from the as-built structure.');
    }
  });

  return differences;
}

/**
 * Compare an as-designed Program Design diagram against an as-built one
 * (AC2). Structural (file-tree/call-stack) changes only — nodes AND edges of
 * the flowchart representation. A pure local-variable rename never appears
 * as a node/edge difference because the flowchart representation never
 * captures variable names in the first place, so identical flowchart
 * structure on both sides is guaranteed to produce MATCHED regardless of any
 * internal rename.
 * @param {string|object} asDesignedInput
 * @param {string|object} asBuiltInput
 * @returns {{status:string, label:string, differences:string[]}}
 */
function compareProgramDesign(asDesignedInput, asBuiltInput) {
  const asDesigned = _asFlowchart(asDesignedInput);
  const asBuilt = _asFlowchart(asBuiltInput);
  const differences = _diffNodesAndEdges(asDesigned, asBuilt, { includeNodes: true });
  return _buildSignal(differences);
}

/**
 * Compare an as-designed System Architecture diagram against an as-built one
 * (AC3). Scoped to new/removed service-to-service calls (edges) only, per
 * this story's DoR — node-only additions are out of this rule's scope.
 * @param {string|object} asDesignedInput
 * @param {string|object} asBuiltInput
 * @returns {{status:string, label:string, differences:string[]}}
 */
function compareSystemArchitecture(asDesignedInput, asBuiltInput) {
  const asDesigned = _asFlowchart(asDesignedInput);
  const asBuilt = _asFlowchart(asBuiltInput);
  const differences = _diffNodesAndEdges(asDesigned, asBuilt, { includeNodes: false });
  return _buildSignal(differences);
}

// ---------------------------------------------------------------------------
// Orchestration + canvas surfacing
// ---------------------------------------------------------------------------

const DIAGRAM_LABELS = {
  'data-model': 'Data Model',
  'program-design': 'Program Design',
  'system-architecture': 'System Architecture'
};

/**
 * Run the drift comparison for whichever diagram types are supplied and log
 * an audit event per comparison (NFR — matched/diverged, per diagram type,
 * per feature; this is the evidence P3/M1 measurement depends on).
 * @param {{dataModel?:{asDesigned,asBuilt}, programDesign?:{asDesigned,asBuilt}, systemArchitecture?:{asDesigned,asBuilt}, featureSlug?:string}} options
 * @returns {{dataModel?:object, programDesign?:object, systemArchitecture?:object}}
 */
function runDriftCheck(options) {
  options = options || {};
  const results = {};

  if (options.dataModel) {
    results.dataModel = compareDataModel(options.dataModel.asDesigned, options.dataModel.asBuilt);
    _logEvent('drift-check-result', {
      diagramType: 'data-model',
      featureSlug: options.featureSlug || null,
      status: results.dataModel.status,
      differenceCount: results.dataModel.differences.length
    });
  }
  if (options.programDesign) {
    results.programDesign = compareProgramDesign(options.programDesign.asDesigned, options.programDesign.asBuilt);
    _logEvent('drift-check-result', {
      diagramType: 'program-design',
      featureSlug: options.featureSlug || null,
      status: results.programDesign.status,
      differenceCount: results.programDesign.differences.length
    });
  }
  if (options.systemArchitecture) {
    results.systemArchitecture = compareSystemArchitecture(options.systemArchitecture.asDesigned, options.systemArchitecture.asBuilt);
    _logEvent('drift-check-result', {
      diagramType: 'system-architecture',
      featureSlug: options.featureSlug || null,
      status: results.systemArchitecture.status,
      differenceCount: results.systemArchitecture.differences.length
    });
  }

  return results;
}

/**
 * Build the canvas content-block that surfaces the drift signal (AC4, AC5),
 * reusing the existing generic canvas-block rendering mechanism (ADR-026 —
 * no parallel rendering path; see src/web-ui/routes/skills.js's
 * `renderCanvasBlock()`'s `drift-signal` branch, wired the same way `table`/
 * `text`/`cluster-tree` already are). Each item carries both a `label`
 * ("Matches"/"Diverged") and `differences` array so the signal is conveyed by
 * more than colour alone (NFR: accessibility, WCAG 2.1 AA).
 * @param {{dataModel?:object, programDesign?:object, systemArchitecture?:object}} results
 * @param {{title?:string}} [options]
 * @returns {{type:string, title:string, content:{items:Array}}}
 */
function buildDriftSignalCanvasBlock(results, options) {
  options = options || {};
  results = results || {};

  const order = ['dataModel', 'programDesign', 'systemArchitecture'];
  const typeKeyMap = { dataModel: 'data-model', programDesign: 'program-design', systemArchitecture: 'system-architecture' };

  const items = [];
  order.forEach(function(key) {
    const signal = results[key];
    if (!signal) return;
    const diagramType = typeKeyMap[key];
    items.push({
      diagramType: diagramType,
      diagramLabel: DIAGRAM_LABELS[diagramType],
      status: signal.status,
      label: signal.label,
      differences: signal.differences
    });
  });

  return {
    type: 'drift-signal',
    title: options.title || 'Drift check: as-designed vs as-built',
    content: { items: items }
  };
}

module.exports = {
  parseErDiagramMermaid,
  parseFlowchartMermaid,
  compareDataModel,
  compareProgramDesign,
  compareSystemArchitecture,
  runDriftCheck,
  buildDriftSignalCanvasBlock,
  setLogger,
  // exported for focused unit testing only
  DUPLICATE_SIMILARITY_THRESHOLD
};
